# Helper function to clean markdown formatting
def clean_md(text):
    # Remove markdown bold markers
    text = re.sub(r'\*\*([^*]+)\*\*', r'\1', text)
    # Remove markdown links
    text = re.sub(r'\[([^\]]+)\]\([^)]+\)', r'\1', text)
    # Remove HTML tags
    text = re.sub(r'<[^>]+>', '', text)
    # Remove admonition markers
    text = re.sub(r'!!!.*?"', '', text)
    text = re.sub(r'\?\?\??"', '', text)
    # Clean up extra spaces
    text = text.strip()
    return text

# Chinese text detection
def has_chinese(text):
    return bool(re.search(r'[\u4e00-\u9fff]', text))

# Extract all Chinese text from markdown
def extract_chinese_texts(md_content):
    texts = []
    lines = md_content.split('\n')
    for line in lines:
        line = line.strip()
        if not line:
            continue
        # Skip code blocks, HTML comments
        if line.startswith('```') or line.startswith('<!--') or line.startswith('-->'):
            continue
        if line.startswith('|') and ('---' in line or '---|' in line):
            continue
        cleaned = clean_md(line)
        if has_chinese(cleaned) and len(cleaned) > 1:
            texts.append(cleaned)
    return texts

